  7	class Dijkstra {
  8	
  9	    private static final int UNREACHABLE = Integer.MAX_VALUE;
 10	
 11	    private Dijkstra() {
 12	    }
 13	
 14	    private static final class Edge {
 15	        private final int to;
 16	        private final int weight;
 17	
 18	        private Edge(int to, int weight) {
 19	            this.to = to;
 20	            this.weight = weight;
 21	        }
 22	    }
 23	
 24	    private static final class QueueEntry {
 25	        private final int distance;
 26	        private final int vertex;
 27	
 28	        private QueueEntry(int distance, int vertex) {
 29	            this.distance = distance;
 30	            this.vertex = vertex;
 31	        }
 32	    }
