 34	    static ArrayList<Integer> dijkstra(ArrayList<ArrayList<int[]>> adj, int src) {
 35	        List<List<Edge>> graph = normalizeGraph(adj);
 36	        validateSource(src, graph.size());
 37	
 38	        int[] distances = computeShortestPaths(graph, src);
 39	        return toArrayList(distances);
 40	    }
