 42	    static void addEdge(ArrayList<ArrayList<int[]>> adj, int u, int v, int w) {
 43	        validateAdjacencyList(adj);
 44	        validateVertex(u, adj.size(), "u");
 45	        validateVertex(v, adj.size(), "v");
 46	        validateWeight(w);
 47	
 48	        adj.get(u).add(new int[]{v, w});
 49	        adj.get(v).add(new int[]{u, w});
 50	    }
