 52	    private static List<List<Edge>> normalizeGraph(ArrayList<ArrayList<int[]>> adj) {
 53	        validateAdjacencyList(adj);
 54	
 55	        int vertexCount = adj.size();
 56	        List<List<Edge>> graph = new ArrayList<>(vertexCount);
 57	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 58	            ArrayList<int[]> rawEdges = adj.get(vertex);
 59	            if (rawEdges == null) {
 60	                throw new IllegalArgumentException("Adjacency list contains a null neighbor list at vertex " + vertex);
 61	            }
 62	
 63	            List<Edge> edges = new ArrayList<>(rawEdges.size());
 64	            for (int[] rawEdge : rawEdges) {
 65	                validateRawEdge(rawEdge, vertex);
 66	                int neighbor = rawEdge[0];
 67	                int weight = rawEdge[1];
 68	
 69	                validateVertex(neighbor, vertexCount, "neighbor");
 70	                validateWeight(weight);
 71	                edges.add(new Edge(neighbor, weight));
 72	            }
 73	            graph.add(edges);
 74	        }
 75	        return graph;
 76	    }
