 78	    private static int[] computeShortestPaths(List<List<Edge>> graph, int src) {
 79	        int[] distances = new int[graph.size()];
 80	        Arrays.fill(distances, UNREACHABLE);
 81	        distances[src] = 0;
 82	
 83	        PriorityQueue<QueueEntry> minHeap =
 84	                new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
 85	        minHeap.offer(new QueueEntry(0, src));
 86	
 87	        while (!minHeap.isEmpty()) {
 88	            QueueEntry current = minHeap.poll();
 89	            if (current.distance != distances[current.vertex]) {
 90	                continue;
 91	            }
 92	
 93	            for (Edge edge : graph.get(current.vertex)) {
 94	                long candidateDistance = (long) current.distance + edge.weight;
 95	                if (candidateDistance < distances[edge.to]) {
 96	                    distances[edge.to] = (int) candidateDistance;
 97	                    minHeap.offer(new QueueEntry(distances[edge.to], edge.to));
 98	                }
 99	            }
100	        }
101	
102	        return distances;
103	    }
