105	    private static ArrayList<Integer> toArrayList(int[] distances) {
106	        ArrayList<Integer> result = new ArrayList<>(distances.length);
107	        for (int distance : distances) {
108	            result.add(distance);
109	        }
110	        return result;
111	    }
